import { describe, it, expect } from "vitest";
import { nextGeneration } from "./game-of-life.js";

describe("Game of Life - Next Generation", () => {
  it.todo("should return empty when single live cell dies -- [(0,0)] → []");
  it.todo(
    "should kill live cells with fewer than 2 neighbors (underpopulation) -- [(0,1), (1,1)] → []"
  );
  it.todo(
    "should keep live cells with 2 or 3 neighbors alive (survival) -- L-shape originals survive"
  );
  it.todo(
    "should kill live cell with more than 3 neighbors (overpopulation) -- center (1,1) dies"
  );
  it.todo(
    "should birth dead cell with exactly 3 neighbors (reproduction) -- [(0,0),(1,0),(0,1)] → includes (1,1)"
  );
  it.todo(
    "should leave block still life unchanged -- [(0,0),(1,0),(0,1),(1,1)] → same"
  );
  it.todo(
    "should evolve blinker from vertical to horizontal -- [(0,0),(0,1),(0,2)] → [(-1,1),(0,1),(1,1)]"
  );
  it.todo(
    "should evolve blinker from horizontal back to vertical -- [(-1,1),(0,1),(1,1)] → [(0,0),(0,1),(0,2)]"
  );
});

