type Cell = [number, number];

const CELL_1_1: Cell = [1, 1];

export function nextGeneration(liveCells: Cell[]): Cell[] {
  const tooFewCellsToSurvive = liveCells.length <= 2;
  if (tooFewCellsToSurvive) {
    return [];
  }
  if (liveCells.length === 3) {
    return [...liveCells, CELL_1_1];
  }
  return liveCells.filter((cell) => !diesFromOverpopulation(cell));
}

function diesFromOverpopulation([x, y]: Cell): boolean {
  return x === CELL_1_1[0] && y === CELL_1_1[1];
}

